public class LineAppenderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("appender");
        java.nio.file.Path f = dir.resolve("log.txt");
        java.nio.file.Path g = dir.resolve("other.txt");
        try {
            try {
                LineAppender.appendLine(f, "alpha");
                check("file is created when missing", true, java.nio.file.Files.exists(f));
                check("count after one line", 1, LineAppender.lineCount(f));
                LineAppender.appendLine(f, "beta");
                LineAppender.appendLine(f, "gamma");
                check("count after three lines", 3, LineAppender.lineCount(f));
                check("lines kept in order", "[alpha, beta, gamma]",
                        java.nio.file.Files.exists(f)
                                ? java.nio.file.Files.readAllLines(f).toString()
                                : "(file missing)");
                LineAppender.appendLine(g, "solo");
                check("second file counts independently", 1, LineAppender.lineCount(g));
                check("first file unchanged", 3, LineAppender.lineCount(f));
            } catch (Exception e) {
                check("no unexpected exception", "none", e.getClass().getSimpleName());
            }
        } finally {
            java.nio.file.Files.deleteIfExists(f);
            java.nio.file.Files.deleteIfExists(g);
            java.nio.file.Files.deleteIfExists(dir);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

