public class LineAppender {

    public static void appendLine(java.nio.file.Path p, String line)
            throws java.io.IOException {
        java.nio.file.Files.writeString(p, line + "\n",
                java.nio.file.StandardOpenOption.CREATE,
                java.nio.file.StandardOpenOption.APPEND);
    }

    public static int lineCount(java.nio.file.Path p)
            throws java.io.IOException {
        return java.nio.file.Files.readAllLines(p).size();
    }
}
